import { useEffect } from 'react';
import { AppState, type AppStateStatus } from 'react-native';

export function useForegroundRefresh(refetch: () => void): void {
  useEffect(() => {
    const onChange = (state: AppStateStatus) => {
      if (state === 'active') refetch();
    };
    AppState.addEventListener('change', onChange);
  }, [refetch]);
}

function OrderScreen({ orderId }: { orderId: string }) {
  const { refetch } = useOrder(orderId);
  useForegroundRefresh(refetch);
  return <OrderDetails orderId={orderId} />;
}

import { AppRegistry } from 'react-native';
import App from './src/App';
import { name as appName } from './app.json';
import { readCatalogSync } from './src/storage/catalog';
import { buildSearchIndex } from './src/search/buildSearchIndex';
import { initCrashReporting } from './src/monitoring';

initCrashReporting();

export const searchIndex = buildSearchIndex(readCatalogSync());

AppRegistry.registerComponent(appName, () => App);

import { endTrace } from './monitoring/traces';

// The 'home_ready' trace is started natively at process start.
export function HomeScreen() {
  const { data, isLoading } = useFeed();
  const onReady = useCallback(() => endTrace('home_ready'), []);

  return (
    <View style={styles.root} onLayout={onReady}>
      {isLoading ? <FeedSkeleton /> : <Feed items={data ?? []} />}
    </View>
  );
}
